import type { IndexPreset } from "@/config/defaults/defaults";
import type { StateCode } from "@/config/defaults/stateTaxTable";
import type { Cents, Micros } from "@/types/units";

export const LOAN_TERMS = [15, 20, 30] as const;
export type LoanTerm = (typeof LOAN_TERMS)[number];

export type DownPaymentMode = "percent" | "amount";

/** Closing cost lines the user can fill in. None is estimated for them (PRD 2.2). */
export const CLOSING_LINES = [
	{ id: "lender", label: "Lender fees" },
	{ id: "title", label: "Title and settlement fees" },
	{ id: "prepaids", label: "Prepaids and escrow deposits" },
	{
		id: "other",
		label: "Other closing costs",
		hint: "Enter one total here if you have no breakdown.",
	},
] as const;
export type ClosingLineId = (typeof CLOSING_LINES)[number]["id"];
export type ClosingMode = "amount" | "percent";

/** A closing cost typed as dollars or as a percent of the home price. */
export interface ClosingLineInput {
	mode: ClosingMode;
	value: string;
}

export type LoanType = "fixed" | "arm";
export type IndexPresetId = IndexPreset["id"];

/** Fields whose validation message is shown after the user leaves the field. */
export type ErrorField =
	| "homePrice"
	| "downPayment"
	| "interestRate"
	| "annualTaxOverride"
	| "annualInsurance"
	| "extraAnnualInsurance"
	| "monthlyHoa"
	| "monthlyOther"
	| "pmiRate"
	| "armMargin"
	| "armFloor"
	| "armInitialCap"
	| "armPeriodicCap"
	| "armLifetimeCap"
	| `closing:${ClosingLineId}`
	| "closingCredits";

/** Raw text the user typed, plus which down payment form is the source. */
export interface CalculatorInputs {
	homePrice: string;
	downPaymentPercent: string;
	downPaymentAmount: string;
	downPaymentMode: DownPaymentMode;
	termYears: LoanTerm;
	interestRate: string;
	state: StateCode;
	/** Annual property tax typed by the user. Empty means use the state rate. */
	annualTaxOverride: string;
	/** Empty means use the national default. */
	annualInsurance: string;
	/** Optional extra annual premium (flood, wind). Empty means none. */
	extraAnnualInsurance: string;
	monthlyHoa: string;
	/** One optional monthly amount, not a list. */
	monthlyOther: string;
	/** PMI toggle. Only matters when LTV is above 80%. */
	pmiOn: boolean;
	/** Annual PMI rate in percent. Empty means use the default. */
	pmiRate: string;
	loanType: LoanType;
	/** 5/6 ARM terms, percent text. They are read only when loanType is "arm". */
	armMargin: string;
	/** Empty means the floor equals the margin. */
	armFloor: string;
	armInitialCap: string;
	armPeriodicCap: string;
	armLifetimeCap: string;
	armIndexPreset: IndexPresetId;
	closing: Record<ClosingLineId, ClosingLineInput>;
	/** Optional seller or lender credits in dollars. Empty means none. */
	closingCredits: string;
}

export interface CalculatorState {
	inputs: CalculatorInputs;
	touched: Partial<Record<ErrorField, boolean>>;
}

export type EditableField =
	| "homePrice"
	| "downPaymentPercent"
	| "downPaymentAmount"
	| "interestRate"
	| "annualTaxOverride"
	| "annualInsurance"
	| "extraAnnualInsurance"
	| "monthlyHoa"
	| "monthlyOther"
	| "pmiRate"
	| "armMargin"
	| "armFloor"
	| "armInitialCap"
	| "armPeriodicCap"
	| "armLifetimeCap"
	| "closingCredits";

export type CalculatorAction =
	| { type: "edit"; field: EditableField; value: string }
	| { type: "blur"; field: EditableField }
	| { type: "setDownPaymentMode"; mode: DownPaymentMode }
	| { type: "setTerm"; years: LoanTerm }
	| { type: "setState"; state: StateCode }
	| { type: "setPmiOn"; on: boolean }
	| { type: "setLoanType"; loanType: LoanType }
	| { type: "setArmIndexPreset"; preset: IndexPresetId }
	| { type: "editClosingLine"; line: ClosingLineId; value: string }
	| { type: "setClosingMode"; line: ClosingLineId; mode: ClosingMode }
	| { type: "blurClosingLine"; line: ClosingLineId };

export interface LoanDerivation {
	homePrice: Cents;
	downPayment: Cents;
	downPaymentPercent: Micros;
	loanAmount: Cents;
	/**
	 * Monthly principal and interest. For a 5/6 ARM this is the first-period
	 * payment, which holds for months 1 to 60.
	 */
	monthlyPrincipalAndInterest: Cents;
	/** loan / price, in millionths. 80.00% is 800000. */
	ltv: Micros;
	interestRate: Micros;
	termYears: LoanTerm;
}

export type InputErrors = Partial<Record<ErrorField, string>>;

export interface DerivedLoan {
	errors: InputErrors;
	/** Present only when every input is valid. */
	loan: LoanDerivation | null;
}
import { DEFAULTS } from "@/config/defaults/defaults";
import { parseMoney } from "@/lib/money";
import { parseRate } from "@/lib/rate";
import {
	centsToFieldText,
	downPaymentFromPercent,
	MAX_HOME_PRICE,
	microsToPercentText,
	percentFromDownPayment,
} from "./loanMath";
import type {
	CalculatorAction,
	CalculatorInputs,
	CalculatorState,
	EditableField,
	ErrorField,
	LoanTerm,
} from "./types";

export const DEFAULT_TERM: LoanTerm = 30;

const armTerms = DEFAULTS.armTerms.value;

export const initialCalculatorState: CalculatorState = {
	inputs: {
		homePrice: "500,000",
		downPaymentPercent: "20.00",
		downPaymentAmount: "100,000.00",
		downPaymentMode: "percent",
		termYears: DEFAULT_TERM,
		interestRate: "6.50",
		state: "NJ",
		annualTaxOverride: "",
		annualInsurance: "",
		extraAnnualInsurance: "",
		monthlyHoa: "",
		monthlyOther: "",
		pmiOn: true,
		pmiRate: "",
		loanType: "fixed",
		armMargin: microsToPercentText(armTerms.marginMicros),
		armFloor: "",
		armInitialCap: microsToPercentText(armTerms.initialCapMicros),
		armPeriodicCap: microsToPercentText(armTerms.periodicCapMicros),
		armLifetimeCap: microsToPercentText(armTerms.lifetimeCapMicros),
		armIndexPreset: "flat",
		closing: {
			lender: { mode: "amount", value: "" },
			title: { mode: "amount", value: "" },
			prepaids: { mode: "amount", value: "" },
			other: { mode: "amount", value: "" },
		},
		closingCredits: "",
	},
	touched: {},
};

/**
 * Rewrites the non-source down payment field from the source field so both
 * forms agree. Leaves the other field alone when the source is not valid yet.
 */
export const syncDownPayment = (inputs: CalculatorInputs): CalculatorInputs => {
	const price = parseMoney(inputs.homePrice);
	if (!price.ok || price.value <= 0 || price.value > MAX_HOME_PRICE) {
		return inputs;
	}
	if (inputs.downPaymentMode === "percent") {
		const percent = parseRate(inputs.downPaymentPercent);
		if (!percent.ok || percent.value > 1_000_000) return inputs;
		const cents = downPaymentFromPercent(price.value, percent.value);
		return { ...inputs, downPaymentAmount: centsToFieldText(cents) };
	}
	const amount = parseMoney(inputs.downPaymentAmount);
	if (!amount.ok || amount.value > price.value) return inputs;
	const percent = percentFromDownPayment(price.value, amount.value);
	return { ...inputs, downPaymentPercent: microsToPercentText(percent) };
};

/** Edits to these fields can change the synced down payment counterpart. */
const PRICE_LINKED_FIELDS: ReadonlySet<EditableField> = new Set([
	"homePrice",
	"downPaymentPercent",
	"downPaymentAmount",
]);

const errorFieldFor = (field: EditableField): ErrorField =>
	field === "downPaymentPercent" || field === "downPaymentAmount"
		? "downPayment"
		: field;

export const calculatorReducer = (
	state: CalculatorState,
	action: CalculatorAction,
): CalculatorState => {
	switch (action.type) {
		case "edit":
			return {
				...state,
				inputs: { ...state.inputs, [action.field]: action.value },
			};
		case "blur": {
			const touched = { ...state.touched, [errorFieldFor(action.field)]: true };
			// Price and down payment edits both change the synced counterpart.
			const inputs = PRICE_LINKED_FIELDS.has(action.field)
				? syncDownPayment(state.inputs)
				: state.inputs;
			return { inputs, touched };
		}
		case "setDownPaymentMode":
			// Both forms were already synced on blur, so only the source changes.
			return {
				...state,
				inputs: { ...state.inputs, downPaymentMode: action.mode },
			};
		case "setTerm":
			return { ...state, inputs: { ...state.inputs, termYears: action.years } };
		case "setPmiOn":
			return { ...state, inputs: { ...state.inputs, pmiOn: action.on } };
		case "editClosingLine":
			return {
				...state,
				inputs: {
					...state.inputs,
					closing: {
						...state.inputs.closing,
						[action.line]: {
							...state.inputs.closing[action.line],
							value: action.value,
						},
					},
				},
			};
		case "setClosingMode":
			// Dollars and percent are not interchangeable, so the old text is dropped.
			return {
				...state,
				inputs: {
					...state.inputs,
					closing: {
						...state.inputs.closing,
						[action.line]: { mode: action.mode, value: "" },
					},
				},
			};
		case "blurClosingLine":
			return {
				...state,
				touched: { ...state.touched, [`closing:${action.line}`]: true },
			};
		case "setLoanType":
			return {
				...state,
				inputs: { ...state.inputs, loanType: action.loanType },
			};
		case "setArmIndexPreset":
			return {
				...state,
				inputs: { ...state.inputs, armIndexPreset: action.preset },
			};
		case "setState":
			return { ...state, inputs: { ...state.inputs, state: action.state } };
	}
};
import Card from "@/components/ui/Card";
import { hasStaleDefault } from "../assumptions";
import { useCalculatorInputs } from "../hooks/useCalculatorInputs";
import ArmFields from "./ArmFields";
import AssumptionsPanel from "./AssumptionsPanel";
import CashToCloseCard from "./CashToCloseCard";
import ClosingCostsFields from "./ClosingCostsFields";
import DownPaymentFields from "./DownPaymentFields";
import LoanSummary from "./LoanSummary";
import LoanTypeSelector from "./LoanTypeSelector";
import MonthlyCostsFields from "./MonthlyCostsFields";
import MonthlyCostsSummary from "./MonthlyCostsSummary";
import MonthlyEstimateCard from "./MonthlyEstimateCard";
import PmiFields from "./PmiFields";
import PmiSummary from "./PmiSummary";
import PropertyTaxFields from "./PropertyTaxFields";
import PropertyTaxSummary from "./PropertyTaxSummary";
import ScheduleTable from "./ScheduleTable";
import TermSelector from "./TermSelector";
import TextField from "./TextField";

interface LoanCalculatorProps {
	/** Fixes "today" for the stale-default check. Defaults to the current date. */
	today?: Date;
}

const LoanCalculator = ({ today }: LoanCalculatorProps) => {
	const {
		state,
		dispatch,
		derived,
		arm,
		propertyTax,
		monthlyCosts,
		pmi,
		closing,
		results,
		showingLastResult,
	} = useCalculatorInputs(today);
	const { inputs, touched } = state;
	const isArm = inputs.loanType === "arm";
	// Show a message only after the user has left the field.
	const shown = (field: keyof typeof touched) =>
		touched[field]
			? (derived.errors[field] ??
				propertyTax.errors[field] ??
				monthlyCosts.errors[field] ??
				arm.errors[field as keyof typeof arm.errors] ??
				pmi.errors[field] ??
				closing.errors[field])
			: undefined;

	return (
		<div className="grid gap-6">
			<Card>
				<form
					noValidate
					onSubmit={(event) => event.preventDefault()}
					className="grid gap-5 sm:grid-cols-2"
				>
					<TextField
						className="sm:col-span-2"
						label="Home price"
						prefix="$"
						value={inputs.homePrice}
						error={shown("homePrice")}
						onChange={(value) =>
							dispatch({ type: "edit", field: "homePrice", value })
						}
						onBlur={() => dispatch({ type: "blur", field: "homePrice" })}
					/>
					<DownPaymentFields
						mode={inputs.downPaymentMode}
						percent={inputs.downPaymentPercent}
						amount={inputs.downPaymentAmount}
						error={shown("downPayment")}
						onModeChange={(mode) =>
							dispatch({ type: "setDownPaymentMode", mode })
						}
						onPercentChange={(value) =>
							dispatch({ type: "edit", field: "downPaymentPercent", value })
						}
						onAmountChange={(value) =>
							dispatch({ type: "edit", field: "downPaymentAmount", value })
						}
						onBlur={(field) => dispatch({ type: "blur", field })}
					/>
					<LoanTypeSelector
						value={inputs.loanType}
						onChange={(loanType) => dispatch({ type: "setLoanType", loanType })}
					/>
					<TermSelector
						value={inputs.termYears}
						onChange={(years) => dispatch({ type: "setTerm", years })}
					/>
					<TextField
						label={isArm ? "Start rate" : "Interest rate"}
						suffix="%"
						value={inputs.interestRate}
						error={shown("interestRate")}
						onChange={(value) =>
							dispatch({ type: "edit", field: "interestRate", value })
						}
						onBlur={() => dispatch({ type: "blur", field: "interestRate" })}
						{...(isArm
							? { hint: "The rate for months 1 to 60 (the fixed period)." }
							: {})}
					/>
					{isArm ? (
						<ArmFields
							margin={inputs.armMargin}
							floor={inputs.armFloor}
							initialCap={inputs.armInitialCap}
							periodicCap={inputs.armPeriodicCap}
							lifetimeCap={inputs.armLifetimeCap}
							preset={inputs.armIndexPreset}
							errorFor={shown}
							onChange={(field, value) =>
								dispatch({ type: "edit", field, value })
							}
							onBlur={(field) => dispatch({ type: "blur", field })}
							onPresetChange={(preset) =>
								dispatch({ type: "setArmIndexPreset", preset })
							}
						/>
					) : null}
					<PropertyTaxFields
						state={inputs.state}
						override={inputs.annualTaxOverride}
						error={shown("annualTaxOverride")}
						onStateChange={(value) =>
							dispatch({ type: "setState", state: value })
						}
						onOverrideChange={(value) =>
							dispatch({ type: "edit", field: "annualTaxOverride", value })
						}
						onBlur={() =>
							dispatch({ type: "blur", field: "annualTaxOverride" })
						}
					/>
					<MonthlyCostsFields
						values={inputs}
						errorFor={shown}
						onChange={(field, value) =>
							dispatch({ type: "edit", field, value })
						}
						onBlur={(field) => dispatch({ type: "blur", field })}
					/>
					<PmiFields
						required={pmi.required}
						on={inputs.pmiOn}
						rate={inputs.pmiRate}
						error={shown("pmiRate")}
						onToggle={(on) => dispatch({ type: "setPmiOn", on })}
						onRateChange={(value) =>
							dispatch({ type: "edit", field: "pmiRate", value })
						}
						onBlur={() => dispatch({ type: "blur", field: "pmiRate" })}
					/>
					<ClosingCostsFields
						closing={inputs.closing}
						credits={inputs.closingCredits}
						dollars={closing.dollars}
						errorFor={shown}
						onValueChange={(line, value) =>
							dispatch({ type: "editClosingLine", line, value })
						}
						onModeChange={(line, mode) =>
							dispatch({ type: "setClosingMode", line, mode })
						}
						onBlur={(line) => dispatch({ type: "blurClosingLine", line })}
						onCreditsChange={(value) =>
							dispatch({ type: "edit", field: "closingCredits", value })
						}
						onCreditsBlur={() =>
							dispatch({ type: "blur", field: "closingCredits" })
						}
					/>
				</form>
			</Card>
			{showingLastResult ? (
				<p
					role="status"
					className="rounded-md bg-amber-50 p-3 text-sm font-medium text-amber-950 ring-1 ring-amber-400"
				>
					<span aria-hidden="true">⚠ </span>A field has text that is not a
					number. The results below are from your last valid entry.
				</p>
			) : null}
			<MonthlyEstimateCard
				estimate={results.estimate}
				arm={results.arm?.summary ?? null}
				outOfDate={hasStaleDefault(results.assumptions)}
			/>
			<CashToCloseCard closing={results.closing} />
			<LoanSummary loan={results.loan} />
			<PropertyTaxSummary tax={results.tax} />
			<MonthlyCostsSummary costs={results.costs} />
			<PmiSummary result={results.pmi} />
			<AssumptionsPanel items={results.assumptions} />
			{results.schedule ? <ScheduleTable rows={results.schedule} /> : null}
		</div>
	);
};

export default LoanCalculator;

