			    "asOf": "2026-10-30",
			    "value": 240000,
			  },
			  "indexPathPresets": {
			    "asOf": "2026-10-30",
			    "value": [
			      {
			        "id": "flat",
			        "label": "Flat",
			      },
			      {
			        "id": "plus-one-per-year",
			        "label": "+1 point per year",
			      },
			      {
			        "id": "shock",
			        "label": "Shock",
			      },
			    ],
			  },
			  "pmiRate": {
			    "asOf": "2026-10-30",
			    "value": 7500,
			  },
			  "stateTaxRates": {
			    "asOf": "2026-10-30",
			    "value": {
			      "CA": 11000,
			      "FL": 9500,
