			      "TX": 16000,
			    },
			  },
			}
		`);
	});
});

describe("defaults registry units", () => {
	it("types money as Cents and rates as Micros", () => {
		expectTypeOf(DEFAULTS.homeownersInsurance.value).toEqualTypeOf<Cents>();
		expectTypeOf(DEFAULTS.pmiRate.value).toEqualTypeOf<Micros>();
		expectTypeOf(DEFAULTS.armTerms.value.marginMicros).toEqualTypeOf<Micros>();
		expectTypeOf(DEFAULTS.stateTaxRates.value.NY).toEqualTypeOf<Micros>();
	});

	it("rejects plain numbers where Cents or Micros are required", () => {
		const takesCents = (_cents: Cents): void => {};
		const takesMicros = (_micros: Micros): void => {};
		// @ts-expect-error a plain number is not Cents
		takesCents(240000);
		// @ts-expect-error a plain number is not Micros
		takesMicros(7500);
		expect(true).toBe(true);
	});
});
import type { Cents, Micros } from "../../types/units";
import { STATE_TAX_TABLE } from "./stateTaxTable";
import type { DefaultRecord, IsoDate } from "./types";

/**
 * Registry of every illustrative default (PRD 9.2 and 9.3).
 * Money is integer cents, rates are integer millionths.
 * Changing a value requires a new `asOf` in the same change; the guard test
 * in defaults.test.ts fails otherwise.
 */

/** A default older than this many days is shown as "May be out of date". */
export const STALE_AFTER_DAYS = 365;

const MS_PER_DAY = 86_400_000;

const toUtcDay = (iso: IsoDate): number => {
	const [year = Number.NaN, month = Number.NaN, day = Number.NaN] = iso
		.split("-")
		.map(Number);
	return Date.UTC(year, month - 1, day);
};

/**
 * True when `asOf` is more than STALE_AFTER_DAYS before `today`.
 * Exactly 365 days is not stale. Staleness never blocks a calculation.
 */
export const isStale = (asOf: IsoDate, today: Date = new Date()): boolean => {
	const todayUtc = Date.UTC(
		today.getUTCFullYear(),
		today.getUTCMonth(),
		today.getUTCDate(),
	);
	return (todayUtc - toUtcDay(asOf)) / MS_PER_DAY > STALE_AFTER_DAYS;
};

export interface IndexPreset {
	id: "flat" | "plus-one-per-year" | "shock";
	label: string;
}

const AS_OF = "2026-10-30";

export const DEFAULTS = {
	stateTaxRates: STATE_TAX_TABLE,
	homeownersInsurance: {
		/** Annual, flat. Does not scale with home price. $2,400.00 per year. */
		value: 240000 as Cents,
		source:
			"Four public 2026 estimates between $2,377 and $2,543, based on about $300,000 of dwelling coverage",
		asOf: AS_OF,
		confidence: "moderate",
	},
	pmiRate: {
		/** Annual rate on the loan amount. 0.75% per year. */
		value: 7500 as Micros,
		source:
			"Midpoint of the commonly cited 0.5% to 1.0% range. No authoritative rate matrix was found.",
		asOf: AS_OF,
		confidence: "low",
	},
	armTerms: {
		value: {
import type { ParseError } from "@/lib/decimal";
import { parseMoney } from "@/lib/money";
import type { Micros } from "@/types/units";
import { type CalculatorInputs, CLOSING_LINES, type ErrorField } from "./types";

/** Interest and start rates above 30% are rejected (PRD S-10). */
export const MAX_INTEREST_RATE = 300_000 as Micros;

export const RATE_TOO_HIGH = "Interest rate cannot be more than 30%";
export const DOWN_PAYMENT_TOO_HIGH =
	"Down payment cannot be more than the price";

/**
 * Message for a field that failed to parse. `label` reads after "Enter":
 * "a home price" gives "Enter a home price" and "A home price must be a number".
 */
export const parseMessage = (label: string, error: ParseError): string => {
	const sentence = `${label[0]?.toUpperCase()}${label.slice(1)}`;
	switch (error) {
		case "empty":
			return `Enter ${label}`;
		case "negative":
			return `${sentence} cannot be negative`;
		case "too-large":
			return `${sentence} is too large`;
		default:
			return `${sentence} must be a number`;
	}
};

/** Money text fields and the error field that reports each. */
const MONEY_FIELDS: readonly {
	input: keyof CalculatorInputs;
	error: ErrorField;
}[] = [
	{ input: "homePrice", error: "homePrice" },
	{ input: "downPaymentAmount", error: "downPayment" },
	{ input: "annualTaxOverride", error: "annualTaxOverride" },
	{ input: "annualInsurance", error: "annualInsurance" },
	{ input: "extraAnnualInsurance", error: "extraAnnualInsurance" },
	{ input: "monthlyHoa", error: "monthlyHoa" },
	{ input: "monthlyOther", error: "monthlyOther" },
	{ input: "closingCredits", error: "closingCredits" },
];

/**
 * Money fields whose text is not a number at all (letters, stray symbols).
 * Blank is not included: a blank required field has no result to keep, and a
 * blank optional field is valid. The dollar down payment counts only while it
 * is the field the user types in.
 */
export const nonNumericMoneyFields = (
	inputs: CalculatorInputs,
): Set<ErrorField> => {
	const bad = new Set<ErrorField>();
	for (const { input, error } of MONEY_FIELDS) {
		if (input === "downPaymentAmount" && inputs.downPaymentMode !== "amount") {
			continue;
		}
		const text = inputs[input];
		if (typeof text !== "string" || text.trim() === "") continue;
		const parsed = parseMoney(text);
		if (!parsed.ok && parsed.error === "invalid") bad.add(error);
	}
	// A percent line is a rate, not money, so only dollar lines count here.
	for (const { id } of CLOSING_LINES) {
		const line = inputs.closing[id];
		if (line.mode !== "amount" || line.value.trim() === "") continue;
		const parsed = parseMoney(line.value);
		if (!parsed.ok && parsed.error === "invalid") bad.add(`closing:${id}`);
	}
	return bad;
};

/**
 * True when every error is non-numeric text in a money field. Then the page
 * keeps the last valid result visible instead of clearing it. Any other error
 * (a rate out of range, a down payment above the price, a blank price) shows
 * no result.
 */
export const keepsLastResult = (
	errors: Partial<Record<ErrorField, string | undefined>>,
	inputs: CalculatorInputs,
): boolean => {
	const failing = Object.entries(errors)
		.filter(([, message]) => message !== undefined)
		.map(([field]) => field as ErrorField);
	if (failing.length === 0) return false;
	const text = nonNumericMoneyFields(inputs);
	return failing.every((field) => text.has(field));
};

