export interface MonthlyEstimate {
	/** Lender payment (escrow) lines: P&I, tax, insurance and PMI when on. */
	lender: EstimateLine[];
	lenderPayment: Cents;
	/** Non-escrow lines: HOA and other monthly costs. */
	nonEscrow: EstimateLine[];
