								<dl>
									{estimate.lender.map((line) => (
										<Pair
											key={line.id}
											label={line.label}
											value={formatMoney(line.amount)}
										/>
									))}
									<Pair
										label="Lender payment (escrow)"
										value={formatMoney(estimate.lenderPayment)}
