			const pmi = [...document.querySelectorAll("label")].find((l) =>
				l.textContent.includes("Include PMI"),
			);
			const box = document.getElementById(pmi.htmlFor);
			for (let i = 0; i < 6; i++) out.push(await sample(() => box.click()));
			return out;
		},
		"schedule yearly/monthly (360 rows, 6 clicks)": async () => {
			const out = [];
			for (const t of ["Monthly", "Yearly", "Monthly", "Yearly", "Monthly", "Yearly"]) {
				out.push(await sample(clickButton(t)));
			}
			return out;
		},
		"type extra payment with 360-row table shown": async () => {
			await sample(clickButton("Monthly"));
			const out = await typeKeys("Extra payment each month (optional)", "3000");
			await sample(clickButton("Yearly"));
			return out;
		},
	};

	window.__perf = {
		names: Object.keys(scenarios),
		run: async (name) => {
			longTasks.length = 0;
			const samples = await scenarios[name]();
			return { samples, longTasks: [...longTasks] };
		},
		reset: () => {
			// Back to the default inputs between scenarios.
			location.reload();
		},
	};
})();
