const results = {};
for (const rate of rates) {
	await send("Emulation.setCPUThrottlingRate", { rate });
	await load();
	const names = await evaluate("window.__perf.names");
	results[rate] = {};
	for (const name of names) {
		await load(); // fresh default state per scenario
		const { samples, longTasks } = await evaluate(`window.__perf.run(${JSON.stringify(name)})`);
		const result = samples.map((s) => s.result).filter((x) => !Number.isNaN(x));
		const input = samples.map((s) => s.input);
		const sync = samples.map((s) => s.sync);
		results[rate][name] = {
			n: samples.length,
			neverChanged: samples.length - result.length,
			syncMax: Math.max(...sync),
			inputMed: pct(input, 0.5), inputMax: Math.max(...input),
			resultMed: pct(result, 0.5), resultP95: pct(result, 0.95), resultMax: Math.max(...result),
			longTasks: longTasks.length, longTaskMax: longTasks.length ? Math.max(...longTasks) : 0,
		};
	}
}
writeFileSync(new URL("./results.json", import.meta.url), JSON.stringify(results, null, 2));
const f = (x) => (Number.isFinite(x) ? x.toFixed(0).padStart(5) : "  n/a");
for (const rate of rates) {
	console.log(`\nCPU throttling ${rate}x`);
	console.log("scenario".padEnd(48), "n  sync  inpMed inpMax resMed resP95 resMax  longtasks(max)");
	for (const [name, r] of Object.entries(results[rate])) {
		console.log(name.padEnd(48), String(r.n).padStart(2), f(r.syncMax), f(r.inputMed), f(r.inputMax), f(r.resultMed), f(r.resultP95), f(r.resultMax), ` ${r.longTasks}(${r.longTaskMax.toFixed(0)})`, r.neverChanged ? `NOCHANGE:${r.neverChanged}` : "");
	}
}
ws.close();
chrome.kill();
process.exit(0);
