export PATH=$PATH:~/.local/bin && yarn build 2>&1 | tail -1; (yarn serve -s dist -l 4173 >/tmp/claude-1000/serve.log 2>&1 &); sleep 3
cd /tmp/claude-1000/axe && cat > audit.mjs <<'EOF'
import { readFileSync, writeFileSync } from "node:fs";
import { spawn } from "node:child_process";
const PORT = 9334;
const axeSrc = readFileSync(new URL("./axe.min.js", import.meta.url), "utf8");
const chrome = spawn("google-chrome", ["--headless=new","--no-sandbox","--disable-gpu",`--remote-debugging-port=${PORT}`,"--user-data-dir=/tmp/claude-1000/axe-profile","--window-size=360,900","about:blank"],{stdio:"ignore"});
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let targets;
for (let i=0;i<50;i++){try{targets=await (await fetch(`http://127.0.0.1:${PORT}/json`)).json();if(targets.length)break;}catch{}await sleep(200);}
const ws = new WebSocket(targets.find((t)=>t.type==="page").webSocketDebuggerUrl);
await new Promise((r)=>ws.addEventListener("open",r));
let id=0;const pending=new Map();const loadW=[];
ws.addEventListener("message",(e)=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id);}else if(m.method==="Page.loadEventFired")loadW.splice(0).forEach((f)=>f());});
const send=(method,params={})=>new Promise((res)=>{const n=++id;pending.set(n,res);ws.send(JSON.stringify({id:n,method,params}));});
const evaluate=async(expression)=>{const r=await send("Runtime.evaluate",{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw new Error(JSON.stringify(r.result.exceptionDetails).slice(0,400));return r.result.result.value;};
const load=async(path)=>{const d=new Promise((r)=>loadW.push(r));await send("Page.navigate",{url:`http://localhost:4173${path}`});await d;await sleep(800);await evaluate(axeSrc);await evaluate(helpers);};
const helpers = `
window.$ = {
 frame: () => new Promise((r)=>requestAnimationFrame(()=>setTimeout(r,30))),
 input(label){const l=[...document.querySelectorAll('label')].find(x=>x.textContent.trim()===label);if(!l)throw new Error('no label '+label);return document.getElementById(l.htmlFor)||l.querySelector('input');},
 set(label,v){const i=this.input(label);Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(i,v);i.dispatchEvent(new Event('input',{bubbles:true}));i.dispatchEvent(new Event('focusout',{bubbles:true}));i.dispatchEvent(new Event('blur'));},
 click(label){this.input(label).click();},
 btn(t){[...document.querySelectorAll('button')].find(b=>b.textContent.trim()===t).click();},
};`;
const run = (extra) => evaluate(`(async()=>{
  const r = await axe.run(document,{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa','best-practice']}});
  return r.violations.map(v=>({id:v.id,impact:v.impact,help:v.help,nodes:v.nodes.length,sample:v.nodes.slice(0,3).map(n=>n.target.join(' ')+' :: '+(n.failureSummary||'').split('\\n').slice(0,3).join(' | '))}));})()`);
const states = [
 ["Home /", "/", ""],
 ["Calculator default", "/calculator", ""],
 ["Calculator: ARM + 10% down (PMI) + extras + income + growth", "/calculator", `(async()=>{const $=window.$;$.click('5/6 ARM');await $.frame();$.set('Down payment (%)','10');await $.frame();$.set('Gross monthly income','3000');$.set('Extra payment each month (optional)','200');$.set('Property tax growth per year (optional)','3');await $.frame();await $.frame();})()`],
 ["Calculator: field errors shown", "/calculator", `(async()=>{const $=window.$;$.set('Home price','abc');$.set('Interest rate','99');$.set('Gross monthly income','0');$.set('One-time lump sum (optional)','100');$.set('Lump sum month','');await $.frame();await $.frame();})()`],
 ["Calculator: monthly schedule + above guideline", "/calculator", `(async()=>{const $=window.$;$.set('Gross monthly income','3000');await $.frame();await $.frame();$.btn('Monthly');await $.frame();await $.frame();})()`],
 ["Calculator: print report mounted", "/calculator", `(async()=>{window.dispatchEvent(new Event('beforeprint'));await window.$.frame();})()`],
 ["Compare: fixed vs ARM", "/compare", `(async()=>{const g=[...document.querySelectorAll('fieldset')].find(f=>f.querySelector('legend')?.textContent==='Loan B');[...g.querySelectorAll('label')].find(l=>l.textContent.trim()==='5/6 ARM').querySelector('input').click();await window.$.frame();await window.$.frame();})()`],
 ["Refinance: result", "/refinance", `(async()=>{const $=window.$;$.set('Current loan balance','300000');$.set('Remaining months','300');$.set('Current interest rate','7.5');$.set('New interest rate','6.5');$.set('Refinance costs (optional)','6000');await $.frame();await $.frame();})()`],
 ["Refinance: no saving + error", "/refinance", `(async()=>{const $=window.$;$.set('Current loan balance','300000');$.set('Remaining months','0');$.set('Current interest rate','7.5');$.set('New interest rate','8');await $.frame();await $.frame();})()`],
];
await send("Page.enable");await send("Runtime.enable");
await send("Emulation.setDeviceMetricsOverride",{width:360,height:900,deviceScaleFactor:2,mobile:true});
const out = {};
for (const [name, path, setup] of states) {
  await load(path);
  if (setup) { await evaluate(setup); await sleep(400); }
  out[name] = await run();
}
writeFileSync(new URL("./axe-results.json", import.meta.url), JSON.stringify(out, null, 2));
for (const [name, v] of Object.entries(out)) {
  console.log(`\n== ${name}: ${v.length} violation(s)`);
  for (const x of v) console.log(` [${x.impact}] ${x.id} (${x.nodes}) ${x.help}\n    ${x.sample.join('\n    ')}`);
}
ws.close();chrome.kill();process.exit(0);
EOF
timeout 200 node audit.mjs 2>&1 | head -120

