  const over = (top, under) => top[3] >= 1 ? top : [0,1,2].map(i => top[i]*top[3] + under[i]*(1-top[3])).concat([1]);
  const bgOf = (el) => { const stack = []; for (let e = el; e; e = e.parentElement) { const c = rgba(getComputedStyle(e).backgroundColor); if (c[3] > 0) { stack.push(c); if (c[3] >= 1) break; } } let acc = [255,255,255,1]; for (const c of stack.reverse()) acc = over(c, acc); return acc; };
  const lum = (c) => { const f = (v) => { v /= 255; return v <= 0.03928 ? v/12.92 : Math.pow((v+0.055)/1.055, 2.4); }; return 0.2126*f(c[0]) + 0.7152*f(c[1]) + 0.0722*f(c[2]); };
  const bad = []; let checked = 0;
  for (const el of document.querySelectorAll('body *')) {
    if (![...el.childNodes].some(n => n.nodeType === 3 && n.textContent.trim())) continue;
    const cs = getComputedStyle(el);
    if (cs.visibility === 'hidden' || cs.display === 'none') continue;
    const r = el.getBoundingClientRect(); if (r.width === 0 || r.height === 0) continue;
    const bg = bgOf(el); const fg = over(rgba(cs.color), bg);
    const L1 = lum(fg), L2 = lum(bg); const ratio = (Math.max(L1,L2)+0.05)/(Math.min(L1,L2)+0.05);
    const size = parseFloat(cs.fontSize); const bold = parseInt(cs.fontWeight) >= 700;
    const need = (size >= 24 || (size >= 18.66 && bold)) ? 3 : 4.5;
    checked++;
    if (ratio < need) bad.push(el.tagName.toLowerCase() + ' "' + el.textContent.trim().slice(0,40) + '" ' + ratio.toFixed(2) + ' < ' + need + ' fg=' + cs.color + ' bg=' + cs.backgroundColor);
  }
  return { checked, bad: [...new Set(bad)].slice(0, 15) };
})()`);
'''
