const PORT = 9336;
const chrome = spawn("google-chrome", ["--headless=new","--no-sandbox","--disable-gpu",`--remote-debugging-port=${PORT}`,"--user-data-dir=/tmp/claude-1000/net-profile","--window-size=1000,900","about:blank"],{stdio:"ignore"});
const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));
let targets;for(let i=0;i<50;i++){try{targets=await(await fetch(`http://127.0.0.1:${PORT}/json`)).json();if(targets.length)break;}catch{}await sleep(200);}
const ws=new WebSocket(targets.find(t=>t.type==="page").webSocketDebuggerUrl);await new Promise(r=>ws.addEventListener("open",r));
let id=0;const pend=new Map();const lw=[];const reqs=[];const wsFrames=[];
ws.addEventListener("message",e=>{const m=JSON.parse(e.data);
 if(m.id&&pend.has(m.id)){pend.get(m.id)(m);pend.delete(m.id);}
 else if(m.method==="Page.loadEventFired")lw.splice(0).forEach(f=>f());
 else if(m.method==="Network.requestWillBeSent"){const r=m.params.request;reqs.push({type:m.params.type,method:r.method,url:r.url,postData:r.postData??null,hasPost:r.hasPostData??false,headers:JSON.stringify(r.headers)});}
 else if(m.method==="Network.webSocketCreated"||m.method==="Network.eventSourceMessageReceived")wsFrames.push(m.method);
});
const send=(method,params={})=>new Promise(res=>{const n=++id;pend.set(n,res);ws.send(JSON.stringify({id:n,method,params}));});
const ev=async(x)=>{const r=await send("Runtime.evaluate",{expression:x,returnByValue:true,awaitPromise:true});if(r.result?.exceptionDetails)throw new Error(JSON.stringify(r.result.exceptionDetails).slice(0,300));return r.result.result.value;};
const helpers=`window.$={frame:()=>new Promise(r=>requestAnimationFrame(()=>setTimeout(r,40))),input(l){const x=[...document.querySelectorAll('label')].find(y=>y.textContent.trim()===l);if(!x)throw new Error('no label '+l);return document.getElementById(x.htmlFor)||x.querySelector('input');},set(l,v){const i=this.input(l);Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(i,v);i.dispatchEvent(new Event('input',{bubbles:true}));i.dispatchEvent(new Event('blur'));},btn(t,scope=document){[...scope.querySelectorAll('button')].find(b=>b.textContent.trim()===t||b.getAttribute('aria-label')===t).click();}};`;
const go=async(path)=>{const d=new Promise(r=>lw.push(r));await send("Page.navigate",{url:`http://localhost:4173${path}`});await d;await sleep(700);await ev(helpers);};
await send("Page.enable");await send("Runtime.enable");await send("Network.enable");
await send("Emulation.setDeviceMetricsOverride",{width:1000,height:900,deviceScaleFactor:1,mobile:false});

// Sentinels: values nobody else would send. Checked against every request below.
const S={price:"654,321",rate:"5.4321",income:"87654",debt:"1234",name:"SENTINEL-PRIVACY-NAME",extra:"4321",lump:"12345"};

// 1. Calculator session: inputs, ARM toggle, extras, affordability, save, reopen, delete.
await go("/calculator");
await ev(`(async()=>{const $=window.$;
 $.set('Home price','${S.price}');$.set('Interest rate','${S.rate}');
 $.set('Gross monthly income','${S.income}');$.set('Other monthly debt (optional)','${S.debt}');
 $.set('Extra payment each month (optional)','${S.extra}');$.set('One-time lump sum (optional)','${S.lump}');$.set('Lump sum month','24');
 $.set('Property tax growth per year (optional)','3');await $.frame();
 $.input('5/6 ARM').click();await $.frame();$.input('Fixed rate').click();await $.frame();
 $.btn('Monthly');await $.frame();
 $.set('Scenario name','${S.name}');$.btn('Save');await $.frame();
 $.btn('Open ${S.name}');await $.frame();
 $.btn('Delete ${S.name}');await $.frame();$.btn('Confirm delete');await $.frame();
})()`);
// 2. Print: the real print path (beforeprint report + printToPDF).
await ev(`(async()=>{window.$.set('Scenario name','${S.name}');window.$.btn('Save');await window.$.frame();})()`);
await send("Page.printToPDF",{});
await ev(`window.dispatchEvent(new Event('beforeprint'))`);await sleep(300);
// 3. Compare page: edit, ARM, save.
await go("/compare");
await ev(`(async()=>{const $=window.$;$.set('Home price','${S.price}');$.set('Scenario name','${S.name}');$.btn('Save');await $.frame();})()`);
// 4. Refinance page.
await go("/refinance");
await ev(`(async()=>{const $=window.$;$.set('Current loan balance','${S.price}');$.set('Remaining months','300');$.set('Current interest rate','${S.rate}');$.set('New interest rate','4.4321');$.set('Refinance costs (optional)','${S.lump}');await $.frame();})()`);
await sleep(1000);

const stored = await ev(`Object.keys(localStorage).join(',') + ' | ' + (localStorage.getItem('mortgage-calculator:scenarios')||'').length + ' chars'`);
const byType={};for(const r of reqs)byType[r.type]=(byType[r.type]??0)+1;
const origin=new URL("http://localhost:4173").origin;
const external=reqs.filter(r=>!r.url.startsWith(origin)&&!r.url.startsWith("data:")&&!r.url.startsWith("blob:"));
const nonGet=reqs.filter(r=>r.method!=="GET"||r.hasPost||r.postData);
const needles=Object.values(S).filter(v=>v.length>3).concat(["654321","SENTINEL","5.4321","87654"]);
const leaks=reqs.filter(r=>needles.some(n=>decodeURIComponent(r.url+" "+r.headers+" "+(r.postData??"")).includes(n)));
console.log("Total requests:",reqs.length);
console.log("By resource type:",JSON.stringify(byType));
console.log("Requests to other origins:",external.length,external.map(r=>r.url));
console.log("Non-GET or with a body:",nonGet.length);
console.log("Requests whose URL, headers or body contain any entered value:",leaks.length,leaks.map(r=>r.url));
console.log("WebSocket / EventSource:",wsFrames.length);
console.log("Fetch/XHR/Ping requests:",reqs.filter(r=>["Fetch","XHR","Ping","Beacon"].includes(r.type)).length);
console.log("Unique URLs:");for(const u of [...new Set(reqs.map(r=>r.type+" "+r.url.replace(origin,"")))])console.log("  "+u);
console.log("localStorage:",stored);
ws.close();chrome.kill();process.exit(0);
EOF
